# Manifold (MANIFOLD) – fast robust boolean.
build() {
  unpack MANIFOLD
  cmake_build -DMANIFOLD_JSBIND=OFF -DMANIFOLD_CBIND=OFF -DMANIFOLD_PYBIND=OFF \
    -DMANIFOLD_PAR=ON -DMANIFOLD_CROSS_SECTION=OFF -DMANIFOLD_EXPORT=OFF \
    -DMANIFOLD_DEBUG=OFF -DMANIFOLD_TEST=OFF -DMANIFOLD_DOWNLOADS=OFF \
    -DTBB_ROOT="$LIBDIR/tbb" -DTRACY_ENABLE=OFF
}
